package com.agencytrip.agencytripapi.infrastructure.adapter.out.persistence.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="paquetes") @Getter @Setter @NoArgsConstructor public class PackageEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_paquete") private Integer idPaquete; private String nombre; private String descripcion; private BigDecimal precio; @Column(name="fecha_salida") private LocalDateTime fechaSalida; @Column(name="fecha_regreso") private LocalDateTime fechaRegreso; private int cupos; @Column(name="id_destino") private Integer idDestino; @Column(name="id_transporte") private Integer idTransporte; @Column(name="id_hotel") private Integer idHotel; private boolean estado; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_destino",insertable=false,updatable=false) private DestinationEntity destino; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_transporte",insertable=false,updatable=false) private TransportEntity transporte; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="id_hotel",insertable=false,updatable=false) private HotelEntity hotel; }
